function isValidPlanDirectory(directory) {
  if (directory.trim() === "" || directory !== directory.trim()) {
    return false;
  }
  if (/^(?:[\\/]|[A-Za-z]:[\\/])/.test(directory)) {
    return false;
  }
  return !directory.split(/[\\/]/).some((segment) => segment === "." || segment === "..");
}

class ConfigValidator {
  static validate(config) {
    const errors = [];
    if (typeof config.planDirectory !== "string" || !isValidPlanDirectory(config.planDirectory)) {
      errors.push("Invalid planDirectory: must be a non-empty relative path without . or .. segments.");
    }
    for (const [option, tools] of [["readOnlyTools", config.readOnlyTools], ["writeCapableTools", config.writeCapableTools]]) {
      if (!Array.isArray(tools) || tools.some((tool) => typeof tool !== "string" || tool.trim() === "")) {
        errors.push(`Invalid ${option}: tool names must be non-empty strings.`);
      }
    }
    for (const command of ConfigTypes.getSkillCommands()) {
      if (typeof config.skillMappings?.[command] !== "string" || config.skillMappings[command].trim() === "") {
        errors.push(`Invalid skillMappings.${command}: must be a non-empty string.`);
      }
      if (typeof config.workflow?.agents?.[command] !== "string" || config.workflow.agents[command].trim() === "") {
        errors.push(`Invalid workflow.agents.${command}: must be a non-empty string.`);
      }
    }
    if (typeof config.workflow?.enforced !== "boolean") {
      errors.push("Invalid workflow.enforced: must be a boolean.");
    }
    if (typeof config.workflow?.sidecar !== "boolean") {
      errors.push("Invalid workflow.sidecar: must be a boolean.");
    }
    if (typeof config.workflow?.switchAgents !== "boolean") {
      errors.push("Invalid workflow.switchAgents: must be a boolean.");
    }
    return { valid: errors.length === 0, errors };
  }
  static validateOrThrow(config) {
    const result = this.validate(config);
    if (!result.valid) {
      throw new Error(`Invalid configuration:
${result.errors.join(`
`)}`);
    }
  }
}

// src/config/ConfigLoader.ts
class ConfigLoader {
