    if (Object.keys(value).some((key) => !["agents", "enforced", "sidecar", "switchAgents"].includes(key))) {
      throw new Error("Invalid workflow option.");
    }
    if (value.enforced !== undefined && typeof value.enforced !== "boolean") {
      throw new Error("Invalid workflow.enforced.");
    }
    if (value.sidecar !== undefined && typeof value.sidecar !== "boolean") {
      throw new Error("Invalid workflow.sidecar.");
    }
    if (value.switchAgents !== undefined && typeof value.switchAgents !== "boolean") {
      throw new Error("Invalid workflow.switchAgents.");
    }
    let agents;
    if (value.agents !== undefined) {
      if (!this.isPlainObject(value.agents)) {
        throw new Error("Invalid workflow.agents.");
      }
      agents = {};
      for (const [command, agent] of Object.entries(value.agents)) {
        if (!ConfigTypes.getSkillCommands().includes(command)) {
          throw new Error(`Invalid workflow.agents.${command}.`);
        }
        if (typeof agent !== "string" || agent.trim() === "") {
          throw new Error(`Invalid workflow.agents.${command}.`);
        }
        agents[command] = agent;
