    const readOnlyTools = this.toolNamesOption(options?.readOnlyTools);
    const skillMappings = this.skillMappingsOption(options?.skillMappings);
    const writeCapableTools = this.toolNamesOption(options?.writeCapableTools);
    const workflow = this.workflowOption(options?.workflow);
    return {
      ...enforceTodoTracker === undefined ? {} : { enforceTodoTracker },
      ...goals === undefined ? {} : { goals },
      ...planDirectory === undefined ? {} : { planDirectory },
      ...readOnlyTools === undefined ? {} : { readOnlyTools },
      ...skillMappings === undefined ? {} : { skillMappings },
      ...writeCapableTools === undefined ? {} : { writeCapableTools },
      ...workflow === undefined ? {} : { workflow }
    };
  }
